mapper.select:
SELECT 
FROM ai_business_flow_remote_command
WHERE tenant_id = #{tenantId}
  AND command_key = #{commandKey}
LIMIT 1

SELECT 
FROM ai_business_flow_remote_command
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1

SELECT 
FROM ai_business_flow_remote_command
WHERE command_status = 'REMOTE_SUCCEEDED'
   OR (
    retry_count < #{maxRetryCount}
    AND (
      command_status = 'PENDING'
      OR (command_status = 'RETRY' AND next_retry_time <= #{now})
      OR (command_status = 'PROCESSING' AND (lock_time IS NULL OR lock_time <= #{staleBefore}))
    )
  )
ORDER BY create_time ASC, id ASC
LIMIT #{batchSize}

mapper.update:
UPDATE ai_business_flow_remote_command
SET command_status = 'PROCESSING',
    retry_count = retry_count + 1,
    next_retry_time = NULL,
    lock_owner = #{lockOwner},
    lock_time = #{now},
    error_type = NULL,
    update_time = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND retry_count < #{maxRetryCount}
  AND (
    command_status IN ('PENDING', 'REMOTE_SUCCEEDED')
    OR (command_status = 'RETRY' AND next_retry_time <= #{now})
    OR (command_status = 'PROCESSING' AND (lock_time IS NULL OR lock_time <= #{staleBefore}))
  )

UPDATE ai_business_flow_remote_command
SET command_status = 'REMOTE_SUCCEEDED',
    process_instance_id = #{processInstanceId},
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = NULL,
    remote_succeeded_time = COALESCE(remote_succeeded_time, #{now}),
    update_time = #{now}
WHERE tenant_id = #{command.tenantId}
  AND id = #{command.id}
  AND command_status = 'PROCESSING'
  AND lock_owner = #{command.lockOwner}

UPDATE ai_business_flow_remote_command
SET command_status = #{status},
    next_retry_time = #{nextRetryTime},
    lock_owner = NULL,
    lock_time = NULL,
    error_type = #{errorType},
    update_time = #{now}
WHERE tenant_id = #{command.tenantId}
  AND id = #{command.id}
  AND command_status = 'PROCESSING'
  AND lock_owner = #{command.lockOwner}
